import * as S from './state.mjs';
import * as Staff from './staff.mjs';
import * as P from './personnel.mjs';
import * as W from './world.mjs';
import * as C from './contracts.mjs';
import * as B from './boardroom.mjs';
import {syncOffice,ensureOffice,pendingDecisions,decisionOptions,respondMessage,postMessage} from './newsroom.mjs';
import {createConversation,chooseResponse,conversationValid} from './conversations.mjs';
import {respondRumor} from './world-events.mjs';
import {ensureCalendar} from './calendar-core.mjs';
import {complianceReport,assertCanAdvance} from './compliance.mjs';
export const CHAIN=['AHC','HC','OC','DC','STC','GM','QB','RB','WR','TE','OL','DL','LB','DB','Scout','Medical'];
export function ensureDelegation(s){return s.franchise.delegation??={version:1,preferences:{inbox:true,interviews:true,meetings:true,rumors:true,roster:true,offseason:true,board:true},preferred:null,history:[],seen:[]};}
export function deputy(s){const d=ensureDelegation(s),today=ensureCalendar(s).date,staff=s.franchise.clubs[s.team].staff.filter(c=>!c.userControlled&&c.years>0&&!c.suspended&&(!c.unavailableUntil||c.unavailableUntil<today));const preferred=staff.find(c=>c.id===d.preferred);return preferred||staff.sort((a,b)=>(CHAIN.includes(a.role)?CHAIN.indexOf(a.role):999)-(CHAIN.includes(b.role)?CHAIN.indexOf(b.role):999)||b.rating-a.rating||a.id.localeCompare(b.id))[0]||null;}
function record(s,key,delegate,area,action,details=''){const d=ensureDelegation(s);if(d.seen.includes(key))return false;d.seen.push(key);d.seen=d.seen.slice(-2000);d.history.unshift({key,date:ensureCalendar(s).date,year:s.year,week:s.week,delegateId:delegate.id,name:delegate.name,role:delegate.role,area,action,details});d.history=d.history.slice(0,180);return true;}
export function withDelegatedAuthority(s,fn){const role=s.franchise.role;try{s.franchise.role='Owner';return fn();}finally{s.franchise.role=role;}}
function finishScene(s,delegate,c){if(!conversationValid(s,c))return false;const cinema=s.franchise.cinema;while(cinema.active&&cinema.active.step<2){chooseResponse(s,0);if(!cinema.active)break;}if(c.type==='pre'&&s.live)s.live.interviewDone=true;if(c.type==='post')s.interviewPending=null;record(s,'scene:'+c.key,delegate,'Meetings',c.title,'A supportive message and clear expectations.');return true;}
export function delegateInterview(s,type,delegate=deputy(s)){if(!delegate)throw Error('No available member of staff can cover the interview.');const d=ensureDelegation(s),key=`press:${s.year}:${s.week}:${type}`;if(d.seen.includes(key)){if(type==='post')s.interviewPending=null;return false;}s.franchise.cinema??={active:null,history:[],promises:[]};if(s.franchise.cinema.active){const active=s.franchise.cinema.active;if(!finishScene(s,delegate,active))s.franchise.cinema.active=null;}
 if(type==='pre'){if(!s.live||s.live.interviewDone)return false;}else if(type==='post'){if(!s.lastMatch)return false;s.interviewPending??={type:'post',year:s.year,week:s.week};}
 try{const c=createConversation(s,type);s.franchise.cinema.active=c;finishScene(s,delegate,c);}catch(e){if(!/already complete|not available/.test(e.message))throw e;if(type==='post')s.interviewPending=null;}
 const club=s.franchise.clubs[s.team];club.owner.patience=Math.min(99,club.owner.patience+.3);record(s,key,delegate,'Media',type==='post'?'Postgame press conference':'Pregame press conference','The staff backed the players and took responsibility for preparation.');return true;}
function choiceFor(m,p,delegate){const options=decisionOptions(m);let id=m.decision==='recovery'?'patient':m.decision==='social'?'private':m.decision==='leadership'?'praise':m.decision==='team'?'unite':m.decision==='expectations'?'steady':m.decision==='contract'?'clarity':p?.persona?.ambition>.75&&delegate.personality==='Motivator'?'challenge':'private';return options.find(c=>c.id===id)?.id||options[0].id;}
export function handleDelegatedOffice(s){const d=ensureDelegation(s),delegate=deputy(s);if(!delegate)throw Error('No available assistant or senior staff member can take charge. Hire a coach or end the holiday.');if(s.live&&!s.live.finished){if(d.preferences.interviews)delegateInterview(s,'pre',delegate);return delegate;}
 syncOffice(s);const office=ensureOffice(s);
 if(d.preferences.meetings){const cinema=s.franchise.cinema;if(cinema?.active){if(!finishScene(s,delegate,cinema.active))cinema.active=null;}for(const promise of cinema?.promises||[]){if(promise.done||promise.year>s.year||promise.year===s.year&&s.week<promise.due)continue;const p=s.roster.find(p=>p.id===promise.playerId);if(!p){promise.done=true;promise.outcome='Player left the club';continue;}if(p.meetingWeek!==`${s.year}:${s.week}`)W.meeting(s,p.id,'Support');promise.done=true;promise.outcome=`Role reviewed by ${delegate.name}`;record(s,'promise:'+promise.playerId+':'+promise.year+':'+promise.week,delegate,'Players','Completed a promised role review',p.name);}}
 if(d.preferences.inbox){for(const m of pendingDecisions(s)){const p=s.roster.find(p=>p.id===m.playerId),choice=choiceFor(m,p,delegate);respondMessage(s,m.id,choice,{delegated:true});m.delegatedBy={id:delegate.id,name:delegate.name,role:delegate.role,date:ensureCalendar(s).date};m.outcome=`${delegate.name} handled this on your behalf. ${m.response}`;record(s,'inbox:'+m.id,delegate,'Inbox',m.title,m.response);}
 for(const m of office.messages.filter(m=>m.team===s.team&&!m.read)){m.read=true;m.handledBy=delegate.name;record(s,'read:'+m.id,delegate,'Inbox','Reviewed '+m.title);}}
 if(d.preferences.rumors)for(const r of s.franchise.world?.rumors||[]){if(r.team!==s.team||r.response||!['Developing','Confirmed'].includes(r.status))continue;respondRumor(s,r.id,'Private contact');record(s,'rumor:'+r.id,delegate,'Media','Addressed '+r.kind,r.name);}
 if(d.preferences.board){const r=B.activeBoardRequest(s);if(r?.status==='meeting'){while(r.status==='meeting')B.answerBoard(s,r.id,r.step,r.step===0?1:0);record(s,'board:'+r.id,delegate,'Ownership',r.kind+' proposal: '+r.outcome,r.line);}}
 if(d.preferences.interviews&&s.interviewPending)delegateInterview(s,'post',delegate);
 return delegate;}
export function delegatedRoster(s){const d=ensureDelegation(s),delegate=deputy(s);if(!delegate)throw Error('There is no available member of staff to manage the team.');if(!d.preferences.roster){assertCanAdvance(s,{game:s.phase!=='offseason'});return;}
 withDelegatedAuthority(s,()=>{P.trimRoster(s);const minimum={QB:1,RB:1,WR:2,TE:1,OL:5,DL:3,LB:2,CB:2,S:1,K:1};for(const [pos,n]of Object.entries(minimum)){const available=()=>s.roster.filter(p=>p.status==='active'&&p.pos===pos&&!p.injury&&!p.holdout);for(const p of s.roster.filter(p=>p.status==='practice'&&p.pos===pos&&!p.injury&&!p.holdout).sort((a,b)=>b.ovr-a.ovr)){if(available().length>=n)break;if(s.roster.filter(p=>p.status==='active').length>=53){const injured=s.roster.find(q=>q.status==='active'&&q.injury);if(injured)P.movePlayer(s,injured.id,'ir');}if(s.roster.filter(p=>p.status==='active').length<53)P.movePlayer(s,p.id,'active');}
 if(available().length<n){const redundant=s.roster.filter(p=>p.status==='active'&&p.pos!==pos&&!p.starter&&s.roster.filter(q=>q.status==='active'&&q.pos===p.pos&&!q.injury&&!q.holdout).length>(minimum[p.pos]||1)).sort((a,b)=>a.ovr-b.ovr)[0];if(redundant&&s.roster.filter(p=>p.status==='active').length>=53){if(s.roster.filter(p=>p.status==='practice').length<16)P.movePlayer(s,redundant.id,'practice');else C.cut(s,redundant.id);}if(available().length<n&&s.roster.filter(p=>p.status==='active').length<53){const serial=(s.franchise.spawnSerial||0)+1;s.franchise.spawnSerial=serial;const player=S.makePlayer(`delegate-reserve-${s.year}-${serial}`,pos,s.year*401+serial);player.ovr=Math.min(player.ovr,68);player.salary=.8;const contract=S.basicContract(player,s.team,S.financeYear(s));if(S.capLedger(s).room<S.capHit(contract,S.financeYear(s)))throw Error('The staff cannot fill the positional vacancy within the cap.');s.roster.push(player);s.franchise.contracts[player.id]=contract;}}}
 });assertCanAdvance(s,{game:s.phase!=='offseason'});record(s,`roster:${s.year}:${s.week}`,delegate,'Squad','Checked availability, depth and registration');}
export function delegationReport(s){const d=ensureDelegation(s),delegate=deputy(s),date=ensureCalendar(s).date;postMessage(s,'delegation-report:'+date,{title:'Your holiday report',source:delegate?.name||'Football operations',category:'Team',body:`${d.history.filter(h=>h.date===date).length} staff actions are recorded for today. Review the calendar activity log for decisions and outcomes.`,date,read:false});}
